<?php

declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Admin;use Acorn\SafetyHealthcheck\Content\{ContentPublisher,ContentVersionRepository,QuestionRepository};
final class ContentPage{public function render():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);$published=(new ContentVersionRepository)->getPublished();if(isset($_POST['create_draft'])){check_admin_referer('acorn_hc_content');$id=(new ContentPublisher)->createDraftFromPublished(get_current_user_id());echo'<div class="notice notice-success"><p>Draft created: '.(int)$id.'</p></div>';}$questions=(new QuestionRepository)->forVersion((int)$published['id']);echo'<div class="wrap"><h1>Questions &amp; Recommendations</h1><p>Published version '.esc_html($published['version_key']).' is immutable. Create a draft before editing.</p><form method="post">';wp_nonce_field('acorn_hc_content');submit_button('Create draft from published','secondary','create_draft');echo'</form><table class="widefat"><thead><tr><th>Key</th><th>Module</th><th>Question</th><th>Review</th></tr></thead><tbody>';foreach($questions as$q)echo'<tr><td>'.esc_html($q['question_key']).'</td><td>'.esc_html($q['module_key']).'</td><td>'.esc_html($q['question_text']).'</td><td>'.esc_html($q['reviewed_by']?:'Outstanding').'</td></tr>';echo'</tbody></table></div>';}}
